add('Brezilya',614,2462,'Flamengo|Fluminense','Rio de Janeiro','identity','25 Haziran 1995’teki, Renato Gaúcho’nun “göbek golü” ile hatırlanan Fla-Flu hangi statta oynandı?','Maracanã','Morumbi|Mineirão|Beira-Rio','Rio futbolunun simge stadı; Dünya Kupası finallerine de sahne oldu.','Fluminense’nin Maracanã maçları arşivi, 1995 şampiyonluğunu getiren Fla-Flu’yu bu statta oynanan unutulmaz maçlar arasında anlatır.','https://fluminense.com.br/noticia/fluminense-e-os-70-jogos-memoraveis-no-maracana','25 Haziran 1995')
add('Brezilya',199,1023,'Corinthians|Palmeiras','São Paulo','memory','2018 Paulista finalinin 8 Nisan’daki rövanşı, penaltılardan önce nasıl bitti? Sıra: Palmeiras – Corinthians.','0–1','1–1|0–0|1–2','İlk maçın sonucu tersine döndü; toplam eşitlik penaltılara götürdü.','Corinthians rövanşı 1–0 kazandı. İki maçın toplamı eşitlendiği için penaltılara gidildi; Corinthians seriyi 4–3 kazandı.','https://www.palmeiras.com.br/noticias/verdao-e-superado-por-corinthians-nos-penaltis-e-fica-com-o-vice-do-paulista/','8 Nisan 2018 · penaltılardan önce')
add('Arjantin',189,209,'Boca Juniors|River Plate','Buenos Aires','memory','2018 Libertadores finalinin Madrid’deki rövanşı uzatmalar dâhil nasıl bitti? Sıra: River Plate – Boca Juniors.','3–1','2–1|1–1|5–3','İki maçın toplamını değil, yalnız Madrid’deki 120 dakikayı soruyoruz.','River Plate Madrid’deki rövanşı 3–1, finali toplamda 5–3 kazandı. Maç sonucu ile toplam skor aynı değildir.','https://inside.fifa.com/tournaments/mens/clubworldcup/uae2018/news/river-plate-triumph-in-superclasico-libertadores-final','9 Aralık 2018 · 120 dakika')
add('Sırbistan',159,669,'Kızılyıldız|Partizan','Belgrad','memory','5 Ocak 1947’deki ilk Ebedî Derbi’de Kızılyıldız hangi skorla kazandı? Sıra: Kızılyıldız – Partizan.','4–3','2–1|3–2|1–0','Ev sahibi Partizan’dı; sorudaki skor sırası ise Kızılyıldız ile başlıyor.','Kulübün tarih arşivi ilk maçı Partizan 3–4 Kızılyıldız olarak kaydeder. Kızılyıldız’ın skorunu önce yazınca cevap 4–3’tür.','https://www.crvenazvezdafk.com/sr-latn/vesti/na-danasnji-dan---pobeda-u-prvom-vecitom-derbiju','5 Ocak 1947')
add('İtalya',252,1038,'Genoa|Sampdoria','Cenova','identity','Derby della Lanterna’nın iki takımının da evi olan tarihî stadyum hangisidir?','Luigi Ferraris','Artemio Franchi|Renato Dall’Ara|Stadio Olimpico','Stadyum, Marassi adıyla da anılır.','Lega Serie A’nın Genoa – Sampdoria kupa maçı belgesi karşılaşma yerini Luigi Ferraris olarak gösterir.','https://img.legaseriea.it/vimages/66f1a31b/2024-25_CPITA_16MI_UNI_1_GENSAM.pdf','Cenova · Luigi Ferraris')
add('Brezilya',210,6600,'Grêmio|Internacional','Porto Alegre','memory','12 Şubat 1989 Gre-Nal derbisinin skoru neydi? Sıra: Internacional – Grêmio.','2–1','1–0|3–1|2–2','Internacional devreyi geride ve bir kişi eksik kapatmıştı.','Internacional’in tarih arşivine göre Nilson’un iki golüyle maç 2–1’e döndü. Karşılaşma Beira-Rio’da oynandı.','https://internacional.com.br/clube/historia/1980','12 Şubat 1989 · Beira-Rio')
add('Arjantin',1418,1286,'Rosario Central|Newell’s Old Boys','Rosario','timeline','Rosario rekabetinin bu üç şampiyonluğunu en eskiden en yeniye sırala.','Rosario Central’in ilk Nacional şampiyonluğu|Rosario Central’in ikinci Nacional şampiyonluğu|Newell’s Old Boys’un ilk Metropolitano şampiyonluğu','','Nacional ve Metropolitano, dönemin iki farklı şampiyonluk organizasyonuydu.','AFA şampiyonlar listesinde Rosario Central 1971 ve 1973 Nacional, Newell’s Old Boys 1974 Metropolitano şampiyonudur.','https://www.afa.com.ar/im/pages/campeones-de-primera-division','1971 → 1973 → 1974')
add('Türkiye',3840,6,'Adana Demirspor|Adanaspor','Adana','two_shirts','2015’te Adana Demirspor’da bulunan, 2020–21’de Adanaspor forması giyen savunmacı kim?','Hakan Çinemre','Samet Akaydın|Tayyip Talha Sanuç|Emre Akbaba','Soyadı Ç ile başlayan, stoper pozisyonundaki oyuncuyu düşün.','TFF’nin Mart 2015 millî takım listesi Hakan Çinemre’yi Adana Demirspor oyuncusu olarak kaydeder. TFF’nin 20 Şubat 2021 Altınordu – Adanaspor maç kadrosu, Adanaspor dönemini doğrular.',['https://www.tff.org/default.aspx?ftxtID=22520&pageID=284','https://www.tff.org/Default.aspx?macId=219586&pageID=528'],'2015 / 2020–21')
add('Türkiye',120,2463,'Kocaelispor|Sakaryaspor','Kocaeli · Sakarya','memory','28 Mayıs 2021 2. Lig play-off finalinin skoru neydi? Sıra: Kocaelispor – Sakaryaspor.','4–0','2–0|3–1|1–0','Kocaelispor finali gol yemeden kazandı.','TFF play-off kaydı 28 Mayıs 2021’deki finali Kocaelispor 4–0 Sakaryaspor olarak gösterir.','https://www.tff.org/default.aspx?ftxtID=35229&pageID=338','28 Mayıs 2021')
add('Uruguay',1000000861,1000000866,'Peñarol|Nacional','Montevideo','legend','Nacional’in tarih kayıtlarında Peñarol’a karşı 35 Clásico golüyle anılan golcü kim?','Atilio García','Alberto Spencer|Fernando Morena|Héctor Scarone','1938’de Nacional’e katılan, Arjantin doğumlu tarihî santrfor.','Nacional’in tarih yazısı Atilio García’ya Peñarol karşısında 35 Clásico golü yazar. Sayı bu kulüp arşivinin kapsamıyla verilmiştir.','https://nacional.uy/noticias/el-debut-del-historico-atilio-garcia','Nacional arşivi · 35 Clásico golü')
add('Meksika',3631,6711,'Club América|Chivas','Meksiko · Guadalajara','identity','7 Kasım 2012 tarihli resmî açıklamasında Meksikalı futbolcularla oynama geleneğini vurgulayan kulüp hangisidir?','Chivas','Club América|Cruz Azul|Pumas UNAM','Guadalajara’nın kırmızı-beyazlı kulübünü düşün.','Chivas’ın 7 Kasım 2012 açıklaması, takımın Meksikalı futbolcularla oynama geleneğini vurgular. Soru o tarihli açıklamaya dayanır.','https://www.chivasdecorazon.com.mx/es/noticias/17556/Comunicado-de-Prensa','7 Kasım 2012 açıklaması')
